UPDATE payment_allocations AS allocation SET cash_advance_allocation = LEAST(allocation.total_payment - allocation.minimum_payment_portion, selected.amount) FROM transactions AS selected JOIN regz_context ON regz_context.batch_id = selected.transaction_id JOIN balance_components AS component ON component.component_id = selected.transaction_id JOIN statements AS statement_context ON statement_context.statement_id = selected.statement_id JOIN allocation_snapshot_context AS snapshot ON snapshot.account_id = selected.account_id AND snapshot.statement_id = selected.statement_id WHERE allocation.allocation_id = 'ALLOC0000009' AND allocation.account_id = selected.account_id AND selected.transaction_id = (SELECT candidate.transaction_id FROM transactions AS candidate JOIN daily_balances AS balance ON balance.account_id = candidate.account_id AND balance.statement_id = candidate.statement_id AND balance.balance_category = candidate.balance_category WHERE candidate.account_id = allocation.account_id AND candidate.statement_id = allocation.statement_id AND candidate.transaction_type = 'cash_advance' AND balance.balance_date = DATE '2027-10-05' ORDER BY balance.apr_applied DESC LIMIT 1);
